class TestServiceCreate:
    def test_create_minimal(self, svc, mock_repo, fixed_now):
        task = svc.create("Buy milk")
        mock_repo.add.assert_called_once()
        assert task.title == "Buy milk"
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.created_at == fixed_now
        assert task.id == 1

    def test_create_with_all_options(self, svc, mock_repo):
        due = datetime(2025, 12, 1, tzinfo=timezone.utc)
        task = svc.create(
            "Deploy", priority=TaskPriority.HIGH, due_at=due, tags=["urgent", "ops"]
        )
        assert task.priority == TaskPriority.HIGH
        assert task.due_at == due
        assert [t.name for t in task.tags] == ["urgent", "ops"]

    def test_create_strips_title(self, svc):
        task = svc.create("  hello  ")
        assert task.title == "hello"

    def test_create_empty_title_raises(self, svc):
        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("")

    def test_create_whitespace_title_raises(self, svc):
        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("   ")

    def test_create_non_string_title_raises(self, svc):
        with pytest.raises(ValueError, match="must be a string"):
            svc.create(123)  # type: ignore

    def test_create_title_too_long(self, mock_repo, fixed_now):
        svc = TaskService(mock_repo, now=lambda: fixed_now, max_title_length=10)
        with pytest.raises(ValueError, match="10 characters"):
            svc.create("a" * 11)

    def test_create_invalid_priority_raises(self, svc):
        with pytest.raises(ValueError, match="must be a TaskPriority"):
            svc.create("X", priority="high")  # type: ignore

    def test_create_naive_due_at_raises(self, svc):
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("X", due_at=datetime(2025, 1, 1))

    def test_create_non_datetime_due_at_raises(self, svc):
        with pytest.raises(ValueError, match="must be a datetime"):
            svc.create("X", due_at="2025-01-01")  # type: ignore

    def test_create_due_at_converted_to_utc(self, svc):
        eastern = timezone(timedelta(hours=-5))
        due = datetime(2025, 12, 1, 12, 0, tzinfo=eastern)
        task = svc.create("X", due_at=due)
        assert task.due_at.tzinfo == timezone.utc

    def test_create_deduplicates_tags(self, svc):
        task = svc.create("X", tags=["python", "Python", "PYTHON"])
        assert len(task.tags) == 1


