        mock_repo.get.return_value = Task(id=1, title="T", tags=[Tag("python")])
        result = svc.add_tags(1, ["python"])
        assert len(result.tags) == 1

    def test_remove_tag(self, svc, mock_repo):
        mock_repo.get.return_value = Task(id=1, title="T", tags=[Tag("python"), Tag("flask")])
        result = svc.remove_tag(1, "python")
        assert [t.name for t in result.tags] == ["flask"]

