        mock_repo.get.return_value = Task(id=1, title="T", tags=[Tag("python")])
        with pytest.raises(ValueError, match="not attached"):
            svc.remove_tag(1, "rust")


class TestServiceInit:
    def test_max_title_length_zero_raises(self):
        with pytest.raises(ValueError, match="must be positive"):
            TaskService(Mock(spec=TaskRepository), max_title_length=0)

    def test_default_now_callable(self):
        repo = Mock(spec=TaskRepository)
        repo.next_id.return_value = 1
        svc = TaskService(repo)
        task = svc.create("test")
        # Should use real time (just check it's recent)
        assert task.created_at.tzinfo == timezone.utc

